      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória na Heap gerenciada (aproximadamente 7.62 MB em um único frame), disparando uma coleta de lixo síncrona (GC.Collect) que pausou a CPU por 24.57ms. Quando somado ao tempo de processamento da CPU (22.67ms), o frame totalizou 47.24ms, violando o orçamento de 28.57ms (35 FPS) e causando engasgo severo (stuttering).",
      "codigo_refatorado": "using UnityEngine;
using System.Collections.Generic;

public class ProjectilePoolManager : MonoBehaviour
{
    [SerializeField] private GameObject projectilePrefab;
    [SerializeField] private int initialPoolSize = 100;

    private readonly Queue<GameObject> _pool = new Queue<GameObject>();

    private void Awake()
    {
        for (int i = 0; i < initialPoolSize; i++)
        {
            CreateNewInstance();
        }
    }

    private GameObject CreateNewInstance()
    {
        GameObject instance = Instantiate(projectilePrefab, transform);
        instance.SetActive(false);
        _pool.Enqueue(instance);
        return instance;
    }

    public GameObject Spawn(Vector3 position, Quaternion rotation)
    {
        GameObject obj = _pool.Count > 0 ? _pool.Dequeue() : CreateNewInstance();
        obj.transform.position = position;
        obj.transform.rotation = rotation;
        obj.SetActive(true);
        return obj;
    }

    public void Despawn(GameObject obj)
    {
        obj.SetActive(false);
        _pool.Enqueue(obj);
    }
}",
      "explicacao_didatica": "Quando criamos ou destruímos muitos objetos de uma vez (ou alocamos grandes listas/arrays repetidamente), a Unity gera 'lixo' na memória RAM gerenciada. Quando esse lixo acumula, o Garbage Collector (coletor de lixo) precisa pausar a execução do jogo inteiro para varrer a memória, provocando pequenas travadas visíveis (stutter). Usando uma técnica chamada Object Pooling (piscina de objetos), criamos os objetos apenas uma vez no carregamento e apenas os ativamos/desativamos conforme a necessidade, reduzindo a alocação de lixo a zero durante a gameplay."
    }
  ],
  "dicas_level_design": null
}

